def verify():
    assert abs(154 ** 2 / 100 - 237.16) < 1e-9 and abs(100e6 / (math.sqrt(3) * 154e3) - 374.9) < 0.1
    assert abs(345 ** 2 / 300 - 396.75) < 1e-9 and abs(math.sqrt(0.9e-3 / 1e-8) - 300) < 1e-9
    assert abs(0.1 / 0.05 * 100 - 200) < 1e-9 and abs(3 / 0.5 - 6) < 1e-12 and abs(math.sqrt(3) / 0.4 - 4.33) < 0.001
    assert 2000 * 5 / 400 == 25 and abs(1.2 / 0.6 - 2) < 1e-12 and abs(math.degrees(math.asin(0.5)) - 30) < 1e-9
    assert abs((0.3 / 60) / 0.05 * 500 - 50) < 1e-9
    p1 = (8 - 10 + 0.04 * 500) / 0.06; assert abs(p1 - 300) < 1e-9 and abs((10 + 0.02 * p1) - (8 + 0.04 * (500 - p1))) < 1e-9
    assert abs(0.1 * 60 / 10 - 0.6) < 1e-12


if __name__ == "__main__":
    verify()
    write_subject(SUBJECT, U)
